  void sse_encode_unit(void self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
  }

  @protected
  void sse_encode_user(User self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_64(self.uid, serializer);
    sse_encode_String(self.username, serializer);
    sse_encode_opt_String(self.email, serializer);
    sse_encode_opt_String(self.nickname, serializer);
    sse_encode_opt_box_autoadd_u_64(self.avatar, serializer);
    sse_encode_Chrono_Naive(self.createDatetime, serializer);
    sse_encode_Chrono_Naive(self.lastUpdateDatetime, serializer);
  }

  @protected
  void sse_encode_user_resp(UserResp self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_64(self.uid, serializer);
    sse_encode_String(self.username, serializer);
    sse_encode_opt_String(self.email, serializer);
  }

  @protected
  void sse_encode_usize(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }
}

